MAX_VOTE_CHARS = 90
# Стеля виводу голосу. Була 120 при `maxLength` 90; запас схеми виріс на 30 знаків, тож росте й
# вона — інакше довша причина обривалась би вже на каналі, і JSON голосу не розібрався б зовсім
# (`viche_vote_lost` міняє ухвалу, а не лише слова).
VOTE_TOKENS = 160
# Партитурі потрібен СВІЙ бюджет виводу. Спільна стеля `max_tokens` розрахована на репліку (~220),
# а дванадцять тактів це ~800 токенів: JSON обривався на півслові, парс падав, і мовчки вмикався
# запасний план «кожен реагує по разу». Тобто партитуру Mamay викидало щопрогону, а видно було лише
# «щось розмова коротка».
# Стеля виходу партитури рахується з РОЗМІРУ хвилі, а не береться однією великою цифрою.
# 2200 закладались під партитуру на ввесь прогін; хвиля з пʼяти тактів стільки не пише, а велика
# стеля лише запрошує модель писати більше.
SCORE_TOKENS = 2200


def score_cap(beats: int) -> int:
    return max(600, min(SCORE_TOKENS, 240 * beats + 200))


def thesis_cap(beats: int) -> int:
    """Стеля виводу для тез. Замір на живому шлюзі: дванадцять тез коштували 764-816 токенів
    разом із входом, тобто самого виводу близько 180-220 — по 15-18 на тезу при `THESIS_MAX` 60.
    Сорок на тезу — це подвійний запас від заміряного, і саме він потрібен: обрив тут коштує не
    коротшої відповіді, а всього списку, бо схема вимагає рівно стільки тез, скільки тактів."""
    return max(200, min(900, 40 * beats + 120))
# На скільки ділиться бюджет для посланого. Не половина: він іде по одну річ, а віче
# мусить дожити до кінця.
SCOUT_PARTS = 6
SCOUT_SHOW = 3
# ★ Чим саме довідник каже «нічого». Рядки НАЗВАНІ, бо на них дивиться `_packet`: порожня
