NOTHING_FOUND = "у довіднику того немає"
TOOL_SILENT = "інструмент не відповів"
SCOUT_EMPTY = "нічого не дізнався"
EMPTY_FACTS = frozenset({NOTHING_FOUND, TOOL_SILENT, SCOUT_EMPTY})
CHRONICLE_TOKENS = 900
# Стеля виводу судді змісту, і тримає її замір, а не запас.
#
# Заміряно 2026-08-27 у прод-умові (справжній шлюз, MamayLM-Gemma-3-27B-IT-v2.0, temperature=0.0,
